code.cpp:
class Solution {
public:
    int findSpecialInteger(vector<int>& arr) {
        int n = arr.size();
        int idx[3] = {n / 4, n / 2, 3 * n / 4};
        for (int i = 0; i < 3; i++) {
            int c = arr[idx[i]];
            int left = lower_bound(arr.begin(), arr.end(), c) - arr.begin();
            int right = upper_bound(arr.begin(), arr.end(), c) - arr.begin();
            if (right - left > n / 4) return c;
        }
        return -1;
    }
};
